	fd_set readfds;
	sigset_t blockcont, oldmask, waitmask;
	struct sigaction oldcont, wakecont = {0};
	struct termios oldstate, newstate;
	if (tui_active)
		return tui_getch();
	fflush(stdout);
	haveterm = tcgetattr(STDIN_FILENO, &oldstate) == 0;
	if (!haveterm) {
		do {
			n = read(STDIN_FILENO, &chbuf, 1);
		} while (n < 0 && errno == EINTR);
		if (n != 1)
			chbuf[0] = '\0';
		return chbuf[0];
